import React from "react";
import { useNavigate } from "react-router-dom";

const topProducts = [
  {
    title: "Wireless Earbuds",
    img: "data:image/jpeg;base64,",
    desc: "Clear sound and long battery life.",
  },
  {
    title: "Smartphone X",
    img: "data:image/jpeg;base64,",
    desc: "Sleek design with powerful performance.",
  },
   {
    title: "Smartphone X",
    img: "data:image/jpeg;base64,",
    desc: "Sleek design with powerful performance.",
  },
];

const topBrands = [
  {
    name: "Apple",
    logo: "data:image/png;base64,",
  },
  {
    name: "Nike",
    logo: "data:image/png;base64,",
  },
];

const promoCards = [
  {
    title: "Gaming Laptop",
    img: "https://source.unsplash.com/200x200/?laptop,gaming",
    desc: "High-performance for ultimate gameplay.",
  },
  {
    title: "Fitness Watch",
    img: "https://source.unsplash.com/200x200/?fitness,watch",
    desc: "Track your workouts and stay healthy.",
  },
  {
    title: "Headphones",
    img: "https://source.unsplash.com/200x200/?headphones",
    desc: "Immersive sound experience.",
  },
];

const AdPage = () => {
  const navigate = useNavigate();

  return (
    <div className="adpage">
      {/* Banner */}
      <div className="ad-banner">
        <img
          src="https://images-eu.ssl-images-amazon.com/images/G/31/img25/Media/PC_Hero_3000x1200_Asin-toys-2x._CB547414496_.jpg"
          alt="Ad Banner"
        />
      </div>

      {/* Top Products */}
      <section className="top-section">
        <h2>Top Products</h2>
        <div className="card-list">
          {topProducts.map((product, index) => (
            <div
              className="product-card"
              key={index}
              onClick={() => navigate("/products")}
            >
              <img src={product.img} alt={product.title} />
              <h3>{product.title}</h3>
              <p>{product.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Top Brands */}
      <section className="top-section">
        <h2>Top Brands</h2>
        <div className="brand-list">
          {topBrands.map((brand, index) => (
            <div className="brand-card" key={index}>
              <img src={brand.logo} alt={brand.name} />
              <h4>{brand.name}</h4>
            </div>
          ))}
        </div>
      </section>

      {/* Final Promo Cards Section */}
      <section className="top-section">
        <h2>Trending Picks</h2>
        <div className="card-list">
          {promoCards.map((card, index) => (
            <div
              className="product-card"
              key={index}
              onClick={() => navigate("/products")}
            >
              <img src={card.img} alt={card.title} />
              <h3>{card.title}</h3>
              <p>{card.desc}</p>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default AdPage;
